import asyncio
from playwright.async_api import async_playwright
URL='http://127.0.0.1:3304/tests/alunix-r8/runs/V3d/index.html'
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch()
        pg=await b.new_page(viewport={'width':1440,'height':900})
        await pg.goto(URL, wait_until='load')
        await pg.wait_for_timeout(1000)
        # scroll to just above #process, then simulate PageDown repeatedly
        procTop = await pg.evaluate(\"document.getElementById('process').getBoundingClientRect().top + window.scrollY\")
        await pg.evaluate(f'window.scrollTo(0, {procTop} - 50)')
        await pg.wait_for_timeout(500)
        await pg.click('body')
        seen = set()
        for i in range(14):
            data = await pg.evaluate('''() => {
              const bands = document.querySelectorAll('.step-band');
              const vis = [];
              bands.forEach(b => {
                const r = b.getBoundingClientRect();
                if (r.top < window.innerHeight && r.bottom > 0) {
                  const t = b.querySelector('.process-step-title');
                  if (t) vis.push(t.textContent.trim());
                }
              });
              return vis;
            }''')
            for t in data: seen.add(t)
            await pg.keyboard.press('PageDown')
            await pg.wait_for_timeout(700)
        print('seen titles via PageDown walk:', seen)
        await b.close()
asyncio.run(main())
"

